svg.script:

var timeout=250;

var seq;
var startx;
var starty;

var node;
var path;
var xpos;
var ypos;
var index;
var mult = new Array(1,-1,-1,1);
var cnt;

window.addEventListener("load",init);

function init()
{
  setTimeout(initialize,1000);  //Delay for openclipart image capture on upload
}

function initialize()
{
  // default values if none passed
  seq = Array(6,6,18);
  startx = 13;
  starty = 19;

  var qs = location.search;
  if(qs.length!=0)
  {
    startx = 10;
    starty = 10;
    qs = qs.replace("?","");
    var params = qs.split("&");
    for(var i=0;i<params.length;i++)
    {
      var values = params[i].split("=");
      if(values[0]=="x") startx = Number(values[1]);
      if(values[0]=="y") starty = Number(values[1]);
      if(values[0]=="s") seq = values[1].split(",");
      if(values[0]=="t") timeout = values[1];
    }
    if(timeout<250) timeout=250;
    if(startx<0 || startx>20) startx=10;
    if(starty<0 || startx>20) starty=10;
  }

  index = 0;
  cnt = 0;

  xpos = startx;
  ypos = starty;

  node = document.getElementById("start");
  node.setAttribute("cx",startx*25);
  node.setAttribute("cy",starty*25);

  node = document.getElementById("loop");
  node.setAttribute("class","black");
  path = "M"+25*xpos+","+25*ypos;
  node.setAttribute("d",path);

  setTimeout(Draw,100);
}

function Draw()
{
  var x=0;
  var y=0;

  if(cnt%2) {y = seq[index] * mult[cnt%4];}
  else {x = seq[index] * mult[cnt%4];}

  xpos += x;
  ypos += y;

  path += "l"+x*25+","+y*25;
  node.setAttribute("d",path);

  index++;
  if(index>=seq.length) index = 0;

  if(xpos==startx && ypos==starty && index==0)
  {
    node.setAttribute("class","red");
    return;
  }

  cnt++;
  if(cnt<50) setTimeout(Draw,timeout);
}
